// Análise prévia baseada em regras
const intent = $json.intent;
const message = $json.message.toUpperCase();
const conversationCount = $json.conversationCount;
const context = $json.context || {};

// Palavras-chave que indicam escalação urgente
const urgentKeywords = [
  'URGENTE', 'URGENTEMENTE', 'IMEDIATO', 'AGORA',
  'SUPERVISOR', 'GERENTE', 'DIRETOR', 'RECLAMAÇÃO',
  'PROCON', 'CONSUMIDOR', 'PROTEÇÃO', 'DIREITO'
];

// Verificar escalação obrigatória
let shouldEscalate = false;
let reason = '';
let priority = 'normal';

// Regra 1: Intenção é ESCALACAO
if (intent === 'ESCALACAO') {
  shouldEscalate = true;
  reason = 'Solicitação explícita de atendimento humano';
  priority = 'high';
}

// Regra 2: Intenção é RETENÇÃO
if (intent === 'RETENÇÃO') {
  shouldEscalate = true;
  reason = 'Solicitação de cancelamento ou reembolso';
  priority = 'high';
}

// Regra 3: Palavras-chave urgentes
if (!shouldEscalate && urgentKeywords.some(keyword => message.includes(keyword))) {
  shouldEscalate = true;
  reason = 'Mensagem contém indicadores de urgência';
  priority = 'urgent';
}

// Regra 4: Muitas mensagens sem resolução
if (!shouldEscalate && conversationCount >= 5) {
  shouldEscalate = true;
  reason = 'Conversa prolongada sem resolução clara';
  priority = 'normal';
}

// Preparar dados para IA (se necessário)
const needsAI = !shouldEscalate && (intent === 'SUPORTE_TECNICO' || conversationCount >= 3);

return {
  json: {
    shouldEscalate,
    reason,
    priority,
    intent,
    message,
    conversationCount,
    context,
    needsAI,
    ruleBasedDecision: !needsAI
  }
};

