// Processar decisão da IA
const aiDecision = $('IA: Decisão de Escalação').item.json.choices[0].message.content.trim().toUpperCase();
const preAnalysis = $('Análise Prévia').item.json;

const shouldEscalate = aiDecision.includes('ESCALAR');

// Combinar com análise prévia
let finalDecision = shouldEscalate;
let reason = preAnalysis.reason || `IA determinou: ${aiDecision}`;
let priority = preAnalysis.priority || 'normal';

// Ajustar prioridade baseado na decisão
if (shouldEscalate && !preAnalysis.shouldEscalate) {
  // Se IA decidiu escalar mas regras não, verificar urgência
  const urgentIndicators = ['URGENTE', 'IMEDIATO', 'CRÍTICO', 'IMPORTANTE'];
  if (urgentIndicators.some(indicator => preAnalysis.message.includes(indicator))) {
    priority = 'urgent';
  } else if (preAnalysis.intent === 'RETENÇÃO' || preAnalysis.intent === 'ESCALACAO') {
    priority = 'high';
  }
}

return {
  json: {
    shouldEscalate: finalDecision,
    escalated: finalDecision,
    reason: reason,
    priority: priority,
    intent: preAnalysis.intent,
    message: preAnalysis.message,
    conversationCount: preAnalysis.conversationCount,
    decisionMethod: 'ai_analysis',
    aiDecision: aiDecision,
    timestamp: new Date().toISOString()
  }
};

// Combinar decisões (regras + IA)
const preAnalysis = $('Análise Prévia').item.json;
const aiDecision = $('Processar Decisão IA').item.json || null;

// Se análise prévia já decidiu, usar ela
let finalOutput;

if (preAnalysis.ruleBasedDecision && preAnalysis.shouldEscalate) {
  // Decisão baseada em regras
  finalOutput = {
    shouldEscalate: true,
    escalated: true,
    reason: preAnalysis.reason,
    priority: preAnalysis.priority,
    intent: preAnalysis.intent,
    decisionMethod: 'rule_based',
    timestamp: new Date().toISOString()
  };
} else if (aiDecision) {
  // Decisão da IA
  finalOutput = {
    shouldEscalate: aiDecision.escalated,
    escalated: aiDecision.escalated,
    reason: aiDecision.reason,
    priority: aiDecision.priority,
    intent: aiDecision.intent,
    decisionMethod: 'ai_analysis',
    timestamp: aiDecision.timestamp
  };
} else {
  // Não escalar
  finalOutput = {
    shouldEscalate: false,
    escalated: false,
    reason: 'Problema pode ser resolvido pelo bot',
    priority: 'normal',
    intent: preAnalysis.intent,
    decisionMethod: 'rule_based',
    timestamp: new Date().toISOString()
  };
}

return {
  json: finalOutput
};

// Formatar saída final
const decision = $('Combinar Decisões').item.json;

const output = {
  success: true,
  escalated: decision.escalated,
  shouldEscalate: decision.shouldEscalate,
  priority: decision.priority,
  reason: decision.reason,
  intent: decision.intent,
  decisionMethod: decision.decisionMethod,
  timestamp: decision.timestamp,
  recommendation: decision.escalated ? 
    `Escalar para atendimento humano (Prioridade: ${decision.priority})` :
    'Continuar com atendimento automatizado'
};

return {
  json: output
};
